<template>
	<view class="write-page">
		<view class="fixed-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="back-btn" @click="goBack">‹</view>
				<text class="nav-title">写一封信</text>
				<view class="nav-save" @click="submit">投递</view>
			</view>
		</view>

		<scroll-view class="write-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerHeight + 'px' }">
			<view class="paper">
				<textarea
					v-model="form.content"
					class="letter-input"
					placeholder="写给某个还没出现的人。可以慢一点，不必立刻解释自己。"
					placeholder-class="placeholder"
				maxlength="600"
					auto-height
				/>
				<text class="count">{{ form.content.length }} / 600</text>
			</view>

			<view class="form-card">
				<view class="field">
					<view class="field-head">
						<text class="field-title">标签</text>
						<text class="field-note">必填，最多 2 个</text>
					</view>
					<view class="tag-grid">
						<view
							v-for="tag in tagOptions"
							:key="tag"
							class="tag-chip"
							:class="{ active: form.tags.includes(tag) }"
							@click="toggleTag(tag)"
						>
							<text># {{ tag }}</text>
						</view>
					</view>
				</view>

				<view class="switch-row" @click="form.allowReply = !form.allowReply">
					<view>
						<text class="switch-title">允许回信</text>
						<text class="switch-desc">对方可先通过瓶子与你通信</text>
					</view>
					<view class="switch" :class="{ active: form.allowReply }"><text></text></view>
				</view>

				<view class="field">
					<view class="field-head">
						<text class="field-title">过期时间</text>
					</view>
					<view class="option-row">
						<view
							v-for="item in expireOptions"
							:key="item.value"
							class="option-pill"
							:class="{ active: form.expire === item.value }"
							@click="form.expire = item.value"
						>
							<text>{{ item.label }}</text>
						</view>
					</view>
				</view>
			</view>

			<view class="notice">
				<text>漂流信会经过内容安全检查；被拉黑用户之间不会互相看见瓶子。</text>
			</view>

			<view class="bottom-safe"></view>
		</scroll-view>
	</view>
</template>

<script>
import { createNote } from '../../api/note';
import { TAG_OPTIONS } from '../../config';
import { showRequestError } from '../../utils/feedback';
import * as profileGuard from '../../utils/profileGuard';

export default {
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 96,
			tagOptions: TAG_OPTIONS,
			submitting: false,
			expireOptions: [
				{ label: '7 天', value: '7d' },
				{ label: '30 天', value: '30d' },
				{ label: '不过期', value: 'never' }
			],
			form: {
				content: '',
				tags: [],
				allowReply: true,
				expire: '30d'
			}
		};
	},
	onLoad(query) {
		this.setHeaderHeight();
	},
	methods: {
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				this.statusBarHeight = info.statusBarHeight || 44;
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.headerHeight = this.statusBarHeight + Math.round(96 * rpxToPx);
			} catch (error) {
				this.headerHeight = 96;
			}
		},
		toggleTag(tag) {
			if (this.form.tags.includes(tag)) {
				this.form.tags = this.form.tags.filter((item) => item !== tag);
				return;
			}
			if (this.form.tags.length >= 2) {
				uni.showToast({ title: '最多选 2 个标签', icon: 'none' });
				return;
			}
			this.form.tags.push(tag);
		},
		async submit() {
			if (this.submitting) return;
			if (!this.form.content.trim()) {
				uni.showToast({ title: '先写下信件正文', icon: 'none' });
				return;
			}
			if (!this.form.tags.length) {
				uni.showToast({ title: '至少选择 1 个标签', icon: 'none' });
				return;
			}
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '写信' }))) return;
			this.submitting = true;
			try {
				const expiresAt = this.getExpiresAt();
				await createNote({
					type: 'text',
					content: this.form.content.trim(),
					tags: this.form.tags,
					allowReply: this.form.allowReply,
					expiresAt
				});
				uni.showToast({ title: '已放入海面', icon: 'success', duration: 900 });
				setTimeout(() => {
					uni.redirectTo({ url: '/pages/drift/mailbox?tab=sent' });
				}, 900);
			} catch (error) {
				showRequestError(error, '投递失败');
			} finally {
				this.submitting = false;
			}
		},
		getExpiresAt() {
			if (this.form.expire === 'never') return '';
			const days = this.form.expire === '7d' ? 7 : 30;
			const date = new Date();
			date.setDate(date.getDate() + days);
			return date.toISOString();
		},
		goBack() {
			uni.navigateBack();
		}
	}
};
</script>

<style lang="scss" scoped>
.write-page {
	min-height: 100vh;
	background: #f7f3f6;
}

.fixed-header {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 10;
	background: rgba(255, 255, 255, 0.97);
	border-bottom: 1rpx solid #f0e5ea;
}

.nav-bar {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 96rpx;
	padding: 0 28rpx;
}

.back-btn,
.nav-save {
	display: flex;
	align-items: center;
	justify-content: center;
	min-width: 72rpx;
	height: 72rpx;
	color: #d4688a;
	font-size: 28rpx;
	font-weight: 700;
}

.back-btn {
	font-size: 52rpx;
	color: #33262e;
}

.nav-title {
	position: absolute;
	left: 150rpx;
	right: 150rpx;
	text-align: center;
	font-size: 32rpx;
	font-weight: 700;
	color: #221820;
}

.write-scroll {
	height: 100vh;
}

.paper {
	margin: 24rpx;
	padding: 34rpx 30rpx 24rpx;
	border-radius: 24rpx;
	background:
		linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(255, 252, 253, 0.98)),
		repeating-linear-gradient(180deg, transparent 0, transparent 62rpx, rgba(212, 104, 138, 0.08) 63rpx);
	box-shadow: 0 10rpx 28rpx rgba(90, 55, 76, 0.06);
}

.letter-input {
	width: 100%;
	min-height: 500rpx;
	font-size: 29rpx;
	line-height: 1.9;
	color: #33262e;
}

.placeholder {
	color: #c8b9c1;
}

.count {
	display: block;
	margin-top: 20rpx;
	text-align: right;
	font-size: 22rpx;
	color: #b9aab2;
}

.form-card {
	margin: 0 24rpx;
	padding: 4rpx 28rpx;
	border-radius: 24rpx;
	background: #ffffff;
	box-shadow: 0 10rpx 28rpx rgba(90, 55, 76, 0.05);
}

.field {
	padding: 28rpx 0;
}

.field + .field,
.switch-row + .switch-row,
.field + .switch-row,
.switch-row + .field {
	border-top: 1rpx solid #f1ecef;
}

.field-head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 20rpx;
	margin-bottom: 20rpx;
}

.field-title,
.switch-title {
	display: block;
	font-size: 28rpx;
	font-weight: 700;
	color: #241b22;
}

.field-note,
.switch-desc {
	display: block;
	margin-top: 8rpx;
	font-size: 22rpx;
	color: #9c8c95;
}

.tag-grid,
.option-row {
	display: flex;
	flex-wrap: wrap;
	gap: 14rpx;
}

.tag-chip,
.option-pill {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	height: 56rpx;
	padding: 0 20rpx;
	border-radius: 999rpx;
	background: #f7f2f5;
	color: #766870;
	font-size: 24rpx;
}

.tag-chip.active,
.option-pill.active {
	background: #221820;
	color: #ffffff;
	font-weight: 700;
}

.switch-row {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 24rpx;
	padding: 28rpx 0;
}

.switch-row > view:first-child {
	flex: 1;
	min-width: 0;
}

.switch {
	position: relative;
	width: 94rpx;
	height: 54rpx;
	border-radius: 999rpx;
	background: #e8e1e5;
	flex-shrink: 0;
	transition: background 0.2s ease;
}

.switch text {
	position: absolute;
	top: 6rpx;
	left: 6rpx;
	width: 42rpx;
	height: 42rpx;
	border-radius: 50%;
	background: #ffffff;
	box-shadow: 0 4rpx 12rpx rgba(0, 0, 0, 0.12);
	transition: transform 0.2s ease;
}

.switch.active {
	background: #d4688a;
}

.switch.active text {
	transform: translateX(40rpx);
}

.notice {
	margin: 20rpx 24rpx 0;
	padding: 22rpx 26rpx;
	border-radius: 20rpx;
	background: #fff8f3;
	color: #a8794d;
	font-size: 23rpx;
	line-height: 1.6;
}

.bottom-safe {
	height: calc(80rpx + env(safe-area-inset-bottom));
}
</style>
